// app/_layout.tsx
import { SplashScreen, Redirect } from 'expo-router';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { useEffect, useState } from 'react';

export default function RootLayout() {
  const [isProfileSetup, setIsProfileSetup] = useState<boolean | null>(null);

  useEffect(() => {
    async function checkProfile() {
      try {
        const profileData = await AsyncStorage.getItem('userProfile');
        setIsProfileSetup(!!profileData);
      } catch (e) {
        console.error("Error reading profile from AsyncStorage", e);
        setIsProfileSetup(false); // Fallback to profile setup on error
      } finally {
        SplashScreen.hideAsync();
      }
    }
    checkProfile();
  }, []);

  if (isProfileSetup === null) {
    return null; // Or a loading indicator
  }

  if (!isProfileSetup) {
    return <Redirect href="/setup-targets" />;
  }

  return <Tabs />;
}
```

